	SELECT FN_MAKE_DATE_CODE('USER') FROM DUAL

INSERT INTO TB_LOGIN_MASTER (
COMPANY_CODE,
USER_ID,
PASSWORD,
USER_NAME,
STATUS,
FAIL_COUNT,
CREATED_BY,
CREATE_DATE,
UPDATED_BY,
UPDATE_DATE
)
VALUES (
#{companyCode}
, #{userId}
, #{passWord}   
, #{userName}
, #{status}
, #{failCount}
, #{createdBy}
, #{createDate}
, #{updatedBy}
, #{updateDate}
)

INSERT INTO TB_USER_MASTER (
COMPANY_CODE,
USER_ID,
USER_NAME,
SALARY,
DEPT,
JOB_TITLE,
POSITION,
ROLE_CODE,
CREATED_BY,
CREATE_DATE,
UPDATED_BY,
UPDATE_DATE
)
VALUES (
#{companyCode}
, #{userId}
, #{userName}
, #{salary}
, #{dept}
, #{jobTitle}
, #{position}
, #{roleCode}
, #{createdBy}
, #{createDate}
, #{updatedBy}
, #{updateDate}
)
